import{_ as o,o as e,c as r,ag as n}from"./chunks/plugin-vue_export-helper.BT7B-090.js";const c=JSON.parse('{"title":"Давай поговорим про деньги","description":"","frontmatter":{"site":"pro","title":"Давай поговорим про деньги","date":"2026-11-09T00:00:00.000Z","source":"https://t.me/jfyi_ps/131","head":[["link",{"rel":"canonical","href":"https://oleg-sidorkin.ru/posts/2026-11-09-davay-pogovorim-pro-dengi"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Давай поговорим про деньги"}],["meta",{"property":"og:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"property":"og:url","content":"https://oleg-sidorkin.ru/posts/2026-11-09-davay-pogovorim-pro-dengi"}],["meta",{"property":"og:image","content":"https://oleg-sidorkin.ru/og.png"}],["meta",{"property":"og:site_name","content":"Oleg Sidorkin"}],["meta",{"property":"og:locale","content":"ru_RU"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Давай поговорим про деньги"}],["meta",{"name":"twitter:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"name":"twitter:image","content":"https://oleg-sidorkin.ru/og.png"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BlogPosting\\",\\"headline\\":\\"Давай поговорим про деньги\\",\\"description\\":\\"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы.\\",\\"url\\":\\"https://oleg-sidorkin.ru/posts/2026-11-09-davay-pogovorim-pro-dengi\\",\\"inLanguage\\":\\"ru-RU\\",\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"Oleg Sidorkin\\",\\"alternateName\\":\\"alterfo\\",\\"url\\":\\"https://oleg-sidorkin.ru\\",\\"jobTitle\\":\\"Software Engineer\\",\\"knowsAbout\\":[\\"Music\\",\\"Audio DSP\\",\\"AI\\",\\"RAG\\",\\"Frontend Development\\",\\"Solution Architecture\\"],\\"sameAs\\":[\\"https://github.com/alterfo\\"]},\\"datePublished\\":\\"2026-11-09\\"}"]]},"headers":[],"relativePath":"posts/2026-11-09-davay-pogovorim-pro-dengi.md","filePath":"posts/2026-11-09-davay-pogovorim-pro-dengi.md"}'),p={name:"posts/2026-11-09-davay-pogovorim-pro-dengi.md"};function a(i,t,s,g,m,d){return e(),r("div",null,[...t[0]||(t[0]=[n("<p>Точнее, про то, как вы их сливаете из-за кривых процессов.</p><p>Всё, что нужно знать про Agile: это про деньги. А не про сраные церемонии.</p><p>Первое и основное <strong>— договоренности.</strong> Без них ваш проект — это паноптикум. И да, с новичками тоже нужно договариваться. Договоренности должны быть зафиксированы. Встреча, по итогу которой нет ни одной чёткой договоренности, — это просто дорогое собрание любителей по%бать мозг. Деньги на ветер.</p><p>Второе <strong>— рука на пульсе.</strong> Снятие статуса (дейли, стендап) может превращаться в обсуждение проблем, но только если вы заранее об этом договорились. Статус — это глаголы совершенного вида. То есть результаты: сделал, сходил, посчитал. Делаю, продолжаю, работаю — это не статус. Это отмазка. Желательно снимать статус стоя. Лучше — в планке. Артефакт снятия статуса — движение задач по доске. Если статус два дня подряд один и тот же — стоп машина. Решаем проблему всем подъездом.</p><p>Третье — это когда <strong>вместо</strong> PBR вам презентуют аналитику, <strong>вместо</strong> ретроспективы коллективное нытьё, а задачи оценивают по скриншоту <strong>вместо</strong> вдумчивого планирования. В приглашении на встречу должны быть чётко очерчены границы и формат. Подрывать встречи, на которых 20 человек с выключенными камерами и без шаринга экрана тупо слушают как двое спорят, — моё любимое занятие.</p><p>А теперь самое ценное, что я могу вам дать. Договоренность на берегу, с помощью которой можно делать проекты за полгода вместо двух лет:</p><p>&quot;Предлагаю работать так: мы встречаемся или созваниваемся каждый день в одно и то же время. Вы говорите что <strong>с-с</strong>делано за сутки и что будет <strong>с-с</strong>делано к следующей встрече. Если вы на следующий день приходите и говорите, что не сделали обещанное, будет вопрос: &quot;WTF!?&quot;. И он будет задан столько раз, сколько нужно, пока мы не поймем причину и не устраним её. Потом нужно будет дать новое обещание. Возражения?&quot;</p><p>Вот и вся методология. А ваши скрам-мастера пусть идут лесом.</p>",8)])])}const u=o(p,[["render",a]]);export{c as __pageData,u as default};
